package br.com.sol7.olimpio.basico.usuariologado.controller;
import br.com.sol7.olimpio.shared.PagedResponse;
import io.smallrye.mutiny.Uni; import jakarta.inject.Inject; import jakarta.validation.Valid; import jakarta.ws.rs.*; import jakarta.ws.rs.core.*; import java.util.List;
import br.com.sol7.olimpio.basico.usuariologado.dto.UsuarioLogadoRequest;
import br.com.sol7.olimpio.basico.usuariologado.dto.UsuarioLogadoResponse;
import br.com.sol7.olimpio.basico.usuariologado.dto.FavoritoDisponivelResponse;
import br.com.sol7.olimpio.basico.usuariologado.service.UsuarioLogadoService;
@Path("/api/basico/usuario-logado") @Produces(MediaType.APPLICATION_JSON) @Consumes(MediaType.APPLICATION_JSON) public class UsuarioLogadoController { @Inject UsuarioLogadoService service; @GET public Uni<List<UsuarioLogadoResponse>> list(){return service.list();} @GET @Path("/paged") public Uni<PagedResponse<UsuarioLogadoResponse>> paged(@QueryParam("page") Integer page,@QueryParam("size") Integer size){return service.paged(page==null?0:page,size==null?10:size);}     @GET @Path("/favoritos") public Uni<PagedResponse<FavoritoDisponivelResponse>> favoritos(@HeaderParam("X-Authenticated-Username") String username, @QueryParam("page") Integer page, @QueryParam("size") Integer size, @QueryParam("busca") String busca){return service.listarFavoritosPaged(username, page==null?0:page, size==null?10:size, busca);}@GET @Path("/{id}") public Uni<UsuarioLogadoResponse> find(@PathParam("id") Long id){return service.find(id);}@POST public Uni<Response> create(@Valid UsuarioLogadoRequest r){return service.create(r).map(item->Response.status(Response.Status.CREATED).entity(item).build());}@PUT @Path("/{id}") public Uni<UsuarioLogadoResponse> update(@PathParam("id") Long id,@Valid UsuarioLogadoRequest r){return service.update(id,r);}@DELETE @Path("/{id}") public Uni<Void> delete(@PathParam("id") Long id){return service.delete(id);} }
